     1	import java.util.List;
     2	
     3	/**
     4	 * The office's building-block offer: a group of exactly three alike components is
     5	 * charged one special block premium instead of the sum of its components.
     6	 *
     7	 * A group that does not match the offer -- too few or too many components, or main
     8	 * items rather than components -- is charged item by item at the listed price.
     9	 */
    10	public class ComponentBlockOffer {
    11	
    12	    private static final int BLOCK_SIZE = 3;
    13	    private static final int BLOCK_BASE_PREMIUM = 60;
    14	
    15	    private final PriceList priceList = new PriceList();
    16	
    17	    public double basePremiumFor(List<Item> alikeItems) {
    18	        if (formsABlock(alikeItems)) {
    19	            return BLOCK_BASE_PREMIUM;
    20	        }
    21	        return listedPriceOf(alikeItems);
    22	    }
    23	
    24	    /**
    25	     * The group is alike by type, so its first item speaks for all of them when the office
    26	     * asks whether it is looking at components.
    27	     */
    28	    private boolean formsABlock(List<Item> alikeItems) {
    29	        return alikeItems.size() == BLOCK_SIZE && priceList.isComponent(alikeItems.get(0));
    30	    }
    31	
    32	    private double listedPriceOf(List<Item> items) {
    33	        double total = 0;
    34	        for (Item item : items) {
    35	            total += priceList.basePremiumFor(item);
    36	        }
    37	        return total;
    38	    }
    39	}
