     7	/**
     8	 * What the office considers "alike" when it looks for a building block.
     9	 *
    10	 * The office reads "alike" as items of the same type: three runes are alike, two runes
    11	 * and a moonstone are not. Groups are kept in the order their first item was insured.
    12	 */
    13	public class AlikeItems {
    14	
    15	    public Collection<List<Item>> groupsIn(List<Item> items) {
    16	        Map<String, List<Item>> byType = new LinkedHashMap<>();
    17	        for (Item item : items) {
    18	            byType.computeIfAbsent(item.type(), type -> new ArrayList<>()).add(item);
    19	        }
    20	        return byType.values();
    21	    }
    22	}
