===== PayoutCalculator.java
     1	/**
     2	 * What the office pays out for an incident reported against a policy.
     3	 *
     4	 * The office settles an incident one damaged item at a time, and the incident's payout is
     5	 * what those settlements come to. The deductible is withheld per damage event, which is why
     6	 * it belongs to the single settlement and not to the tally.
     7	 */
     8	public class PayoutCalculator {
     9	
    10	    private static final int DEDUCTIBLE = 100;
    11	
    12	    private final ReimbursementClauses reimbursementClauses = new ReimbursementClauses();
    13	
    14	    public int payoutFor(Incident incident, InsuredItems insuredItems) {
    15	        double payout = 0;
    16	        for (Damage damage : incident.damages()) {
    17	            payout += settlementFor(damage, insuredItems);
    18	        }
    19	        return OfficesFavour.onAmountPaidOut(payout);
    20	    }
    21	
    22	    /**
    23	     * What one damaged item is settled at: the damage the office reimburses under the
    24	     * clauses that cover it, less the deductible it withholds for every damage event.
    25	     */
    26	    private double settlementFor(Damage damage, InsuredItems insuredItems) {
    27	        return reimbursementClauses.reimbursedAmountFor(damage, insuredItems.coveringItemFor(damage))
    28	                - DEDUCTIBLE;
    29	    }
    30	}
===== ClaimOffice.java
     1	import java.util.ArrayList;
     2	import java.util.List;
     3	
     4	/**
     5	 * Works through a scenario's steps in the order the office received them.
     6	 *
     7	 * The office keeps count of the customer's earlier contracts as it goes, because a quote is
     8	 * assessed against the history that stands before it. Only a quote creates a contract; a claim
     9	 * is made against a policy that already exists and so leaves that history untouched.
    10	 */
    11	public class ClaimOffice {
    12	
    13	    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    14	    private final PayoutCalculator payoutCalculator = new PayoutCalculator();
    15	
    16	    public List<StepResult> run(Scenario scenario) {
    17	        List<StepResult> results = new ArrayList<>();
    18	        int earlierContracts = 0;
    19	        for (Step step : scenario.steps()) {
    20	            if (step instanceof QuoteStep quoteStep) {
    21	                results.add(quote(quoteStep, scenario.customer(), earlierContracts));
    22	                earlierContracts++;
    23	            } else {
    24	                results.add(settle((ClaimStep) step, scenario));
    25	            }
    26	        }
    27	        return results;
    28	    }
    29	
    30	    private QuoteResult quote(QuoteStep quoteStep, Customer customer, int earlierContracts) {
    31	        QuoteAssessment assessment = new QuoteAssessment(customer, earlierContracts);
    32	        return new QuoteResult(premiumCalculator.premiumFor(quoteStep, assessment));
    33	    }
    34	
    35	    private ClaimResult settle(ClaimStep claimStep, Scenario scenario) {
    36	        InsuredItems insuredItems = insuredItemsOf(claimStep, scenario);
    37	        int payout = payoutCalculator.payoutFor(claimStep.incident(), insuredItems);
    38	        return new ClaimResult(payout, insuredItems.cover().remainingCapAfter(payout));
    39	    }
    40	
    41	    private InsuredItems insuredItemsOf(ClaimStep claimStep, Scenario scenario) {
    42	        return new InsuredItems(((QuoteStep) scenario.steps().get(claimStep.policy())).items());
    43	    }
    44	}
